# Load required packages
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Define file paths
file_paths <- c(
  'wave_one_lsype_young_person_2020.tab',
  'wave_two_lsype_young_person_2020.tab',
  'wave_three_lsype_young_person_2020.tab',
  'wave_four_lsype_young_person_2020.tab',
  'wave_five_lsype_young_person_2020.tab',
  'wave_six_lsype_young_person_2020.tab',
  'wave_seven_lsype_young_person_2020.tab',
  'ns8_2015_main_interview.tab',
  'ns9_2022_main_interview.tab'
)

# Load all files
load_files <- function(file_path) {
  read_delim(paste0('data/input/', file_path), delim = '\t')
}

# Load all datasets
datasets <- lapply(file_paths, function(file_path) {
  read_delim(paste0('data/input/', file_path), delim = '\t')
})

# Name each dataset for clarity
names(datasets) <- file_paths

# Merge datasets by NSID
merged_data <- Reduce(function(x, y) full_join(x, y, by = 'NSID'), datasets)

# Define mapping for missing values to standard codes
missing_value_mapping <- function(x) {
  if (is.na(x)) return(-3)
  if (x == -999 | x == -998 | x == -997 | x == -995) return(-2)
  if (x == -92) return(-9)
  if (x == -91) return(-1)
  if (x == -99) return(-3)
  if (x == -9) return(-9)
  if (x == -8) return(-8)
  if (x == -1) return(-1)
  return(x)
}

# Extract and map sex variables
sex_vars <- c(
  W1sexYP = missing_value_mapping(datasets[[1]]$W1sexYP),
  W2SexYP = missing_value_mapping(datasets[[2]]$W2SexYP),
  W3sexYP = missing_value_mapping(datasets[[3]]$W3sexYP),
  W4SexYP = missing_value_mapping(datasets[[4]]$W4SexYP),
  W5SexYP = missing_value_mapping(datasets[[5]]$W5SexYP),
  W6Sex = missing_value_mapping(datasets[[6]]$W6Sex),
  W7Sex = missing_value_mapping(datasets[[7]]$W7Sex),
  W8CMSEX = missing_value_mapping(datasets[[8]]$W8CMSEX),
  W9DSEX = missing_value_mapping(datasets[[9]]$W9DSEX)
)

# Merge sex variables into a single data frame
sex_df <- data.frame(NSID = merged_data$NSID, sex_vars)

# Derive consolidated sex variable using most recent valid response first
derive_sex <- function(row) {
  sex_priority <- c('W9DSEX', 'W8CMSEX', 'W7Sex', 'W6Sex', 'W5SexYP', 'W4SexYP', 'W3sexYP', 'W2SexYP', 'W1sexYP')

  for (var in sex_priority) {
    if (!is.na(row[[var]]) && row[[var]] %in% c(1, 2)) {
      return(row[[var]])
    }
  }
  return(-3)
}

# Apply derive_sex function to each row
merged_data <- merged_data %>%
  mutate(sex = purrr::map2_dbl(
    NSID,
    1:nrow(merged_data),
    ~ derive_sex(sex_df[sex_df$NSID == merged_data$NSID[.y], ])
  ))

# Create labelled factor for sex
merged_data$sex <- factor(merged_data$sex,
                          levels = c(-9, -8, -7, -3, -2, -1, 1, 2),
                          labels = c('Refusal', 'Dont Know', 'Prefer Not to Say', 'Not Interviewed',
                                     'Schedule Not Applicable', 'Not Applicable', 'Male', 'Female'))

# Select only necessary columns: NSID and derived sex
final_data <- merged_data %>%
  select(NSID, sex)

# Write to CSV
write_csv(final_data, 'data/output/cleaned_data.csv')

message('Cleaned data with derived sex variable has been written to data/output/cleaned_data.csv')

